ToString by zahladil rozdíl mezi skutečným číslem a textem. Instanceof dovolí ověřit typ i bezpečně pojmenovat hodnotu. Připravený SafeConstructor a zákaz duplicit řeší parsování; metoda read kontroluje pravidla této aplikace.

`src/main/java/EventConfig.java`:

```java
import java.util.*;
import org.yaml.snakeyaml.*;
import org.yaml.snakeyaml.constructor.SafeConstructor;

public class EventConfig {
  public record Config(int capacity, boolean reminders, String host) {}

  private static Object parse(String yaml) {
    LoaderOptions options = new LoaderOptions();
    options.setAllowDuplicateKeys(false);
    return new Yaml(new SafeConstructor(options)).load(yaml);
  }

  // UPRAVUJ ODSUD
  public static Config read(String yaml) {
    Object root = parse(yaml);
    if (!(root instanceof Map<?, ?> map)) throw new IllegalArgumentException("map required");
    Object capacity = map.get("capacity"), reminders = map.get("reminders"), host = map.get("host");
    if (!(capacity instanceof Integer n) || n < 1 || n > 200)
      throw new IllegalArgumentException("capacity");
    if (!(reminders instanceof Boolean enabled)) throw new IllegalArgumentException("reminders");
    if (!(host instanceof String name) || name.trim().isEmpty())
      throw new IllegalArgumentException("host");
    return new Config(n, enabled, name.trim());
  }
  // UPRAVUJ POTUD
}
```

Příklad doplňujícího testu; celý soubor zachovává i dodané scénáře. `src/test/java/EventConfigTest.java`:

```java
import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;
import org.yaml.snakeyaml.error.YAMLException;

class EventConfigTest {
  @Test
  void acceptsTypedValues() {
    assertEquals(
        new EventConfig.Config(40, true, "Blair"),
        EventConfig.read("capacity: 40\nreminders: true\nhost: ' Blair '\nextra: ignored"));
  }

  @Test
  void boundaries() {
    for (int n : new int[] {1, 200})
      assertEquals(
          n, EventConfig.read("capacity: " + n + "\nreminders: false\nhost: Serena").capacity());
  }

  @Test
  void refusesStringNumbersAndBooleans() {
    for (String yaml :
        new String[] {
          "capacity: '40'\nreminders: true\nhost: Blair",
          "capacity: 40\nreminders: 'false'\nhost: Blair"
        }) assertThrows(IllegalArgumentException.class, () -> EventConfig.read(yaml));
  }

  @Test
  void rejectsMissingAndOutOfRange() {
    for (String yaml :
        new String[] {
          "{}",
          "[]",
          "capacity: 0\nreminders: true\nhost: Blair",
          "capacity: 201\nreminders: true\nhost: Blair",
          "capacity: 4.5\nreminders: true\nhost: Blair",
          "capacity: 40\nreminders: true\nhost: ' '"
        }) assertThrows(IllegalArgumentException.class, () -> EventConfig.read(yaml));
  }

  @Test
  void duplicateKeysStayRejected() {
    assertThrows(
        YAMLException.class,
        () -> EventConfig.read("capacity: 40\ncapacity: 80\nreminders: true\nhost: Blair"));
  }

  @Test
  void rejectsNullHost() {
    assertThrows(
        IllegalArgumentException.class,
        () -> EventConfig.read("capacity: 40\nreminders: true\nhost: null"));
  }
}
```
